NAME = 'GerAlbrecht: German Albrecht Neues Testament und Psalmen'
BOOK = 'Titus'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Knecht Gottes und ein Apostel Jesu Christi, entbietet seinem echten, im Glauben eng mit ihm verbunden Kind Titus seinen Gruß. — Ich bin ja dazu bestellt, Gottes Auserwählte zum Glauben zu führen und die Erkenntnis jener Wahrheit zu verbreiten, die einen frommen Wandel wirkt',
        2: 'durch die Hoffnung auf das ewige Leben, das Gott, der nicht lügen kann, schon von Ewigkeit her in seinem Ratschluß bestimmt hat.',
        3: 'Kundgemacht aber hat er sein Wort zur rechten Zeit durch die Verkündigung, mit der ich betraut worden bin nach dem Auftrag Gottes, unseres Retters —.',
        4: 'Gnade sei mit dir und Friede von Gott dem Vater und unserem Erretter Christus Jesus!',
        5: 'Dies ist der Grund, warum ich dich in Kreta gelassen habe: Du sollst die Dinge, die ich dort noch nicht erledigt, in Ordnung bringen. Vor allem sollst du nach meiner Anweisung in den einzelnen Städten Älteste einsetzen.',
        6: 'Ein Ältester muß unbescholten sein und eines Weibes Mann. Hat er Kinder, so müssen sie im Glauben stehen; sie dürfen nicht den Ruf haben, daß sie ein liederliches Leben führen; auch dürfen sie (ihren Eltern) nicht ungehorsam sein.',
        7: 'Denn jeder Bischof muß ein unbescholtener Mann sein, — er ist ja Gottes Haushalter. — Er darf nicht selbstherrlich sein und nicht zum Zorn neigen. Er darf kein Trinker sein oder ein Mensch, der Händel sucht und schmutzige Gewinnsucht zeigt.',
        8: 'Er soll vielmehr gastfrei sein, dem Guten zugetan, besonnen, gerecht, gottesfürchtig, voller Selbstbeherrschung.',
        9: 'Er muß festhalten an dem zuverlässigen Wort (Gottes), worin er unterrichtet worden ist, damit er fähig sei, auch in der gesunden Lehre zu unterweisen und alle zu widerlegen, die ihre Wahrheit zu bestreiten suchen.',
        10: 'Es gibt ja, namentlich unter den Judenchristen, viele Schwätzer und Verführer, die sich nicht unterordnen wollen.',
        11: 'Diesen Leuten muß der Mund gestopft werden; denn sie machen ganze Familien unglücklich, indem sie aus schmutziger Gewinnsucht ungehörige Lehren vortragen.',
        12: 'Einer ihrer Landsleute, ihr eigener Prophet, hat gesagt: "Kreter sind immer verlogen, sind Tiere und faule Gesellen."',
        13: 'Dies Zeugnis ist wahr. Darum weise sie scharf zurecht, damit sie im Glauben gesund bleiben',
        14: 'und nicht hören auf jüdische Fabeln und auf Gebote solcher Menschen, die der Wahrheit den Rücken kehren!',
        15: 'Den Reinen ist alles rein. Den Schuldbefleckten aber und Ungläubigen ist nichts rein, sondern bei ihnen ist beides befleckt: ihr Sinn und ihr Gewissen.',
        16: 'Sie rühmen sich zwar, Gott zu kennen, doch mit ihren Werken verleugnen sie ihn. Sie sind Gott ein Greuel; denn sie gehorchen ihm nicht und können kein wahrhaft gutes Werk vollbringen.',
    },
    2: {
        1: 'Du aber rede, was der gesunden Lehrer entspricht!',
        2: 'Ermahne die älteren Männer, daß sie nüchtern seien, ehrbar, besonnen, gesund im Glauben, in der liebe und in der Geduld!',
        3: 'Die älteren Frauen halte auch zu einem Wandel an, wie er sich für Heilige geziemt! Sie sollen nicht verleumden, auch nicht dem Laster der Trunksucht frönen, sondern in allem Guten unterweisen:',
        4: 'sie sollen die jüngeren Frauen anleiten, ihre Männer und ihre Kinder liebzuhaben,',
        5: 'sittsam und keusch zu sein, ihr Hauwesen gut in Ordnung zu halten und sich ihren Männern unterzuordnen, damit Gottes Wort nicht verlästert werde.',
        6: 'Ebenso ermahne die jüngeren Männer zur Selbstbeherrschung und Sittsamkeit!',
        7: 'Gib ihnen dabei durch dein Verhalten in jeder Hinsicht ein gutes Vorbild! Verkündige die Lehre unverfälscht und mit würdevollem Vortrag;',
        8: 'jedes deiner Worte sei gesund und einwandfrei: dann werden die Widersacher beschämt und können uns nichts Schlechtes nachsagen.',
        9: 'Den Sklaven schärfe den Gehorsam gegen ihre Herren ein! Sie sollen ihnen in allen Stücken gefällig sein, keine Widerworte haben,',
        10: 'nichts veruntreuen, sondern stets die rechte Treue beweisen, damit sie der Lehre Gottes, unseres Erretters, in jeder Hinsicht Ehre machen.',
        11: 'Denn die Gnade Gottes, die alle Menschen retten kann und will, ist offenbar geworden.',
        12: 'Sie will uns nun dazu erziehen, dem gottlosen Wesen und den weltlichen Lüsten völlig zu entsagen, verständig, gerecht und fromm in dieser Weltzeit zu leben',
        13: 'und darauf zu warten, daß sich unsere beseligende Hoffnung erfülle durch die Erscheinung der Herrlichkeit unseres großen Gottes und Erretters Jesus Christus.',
        14: 'Der hat sich für uns hingegeben, um uns von aller Ungerechtigkeit loszukaufen und sich ein Volk zum Eigentum zu reinigen, das Eifer zeigt für gute Werke.',
        15: 'Das ist es, was du reden sollst. Ermahne und weise zurecht mit allem Nachdruck! Tritt so auf, daß niemand wagt, dich verächtlich zu behandeln!',
    },
    3: {
        1: 'Bringe allen in Erinnerung, daß sie den obrigkeitlichen Gewalten untertan seien, ihren Befehlen gehorchen, sich an allen nützlichen Werken beteiligen,',
        2: 'niemand schmähen, sondern sich friedfertig und nachgiebig zeigen und allen Menschen stets mit Freundlichkeit entgegenkommen!',
        3: 'Auch wir sind ja einst unverständig, ungehorsam und verirrt gewesen; wir haben den mannigfachsten Begierden und Lüsten gedient und in Bosheit und Neid dahingelebt; wir sind verabscheuungswürdig gewesen und haben einander gehaßt.',
        4: 'Als aber die Güte und Menschenfreundlichkeit Gottes, unseres Retters, erschien,',
        5: 'da hat er uns nicht etwas wegen der gerechten Werke, die wir getan, das Heil gebracht; sondern in seinem Erbarmen hat er uns errettet durch das Bad der Wiedergeburt und die Erneuerung, die gewirkt wird durch den Heiligen Geist,',
        6: 'den er durch Jesus Christus, unseren Retter, reichlich über uns ausgegossen hat.',
        7: 'So sollen wir, durch seine Gnade gerechtfertigt, Erben werden des ewigen Lebens, auf das wir hoffen.',
        8: 'Dies ist ein wahres Wort, und du sollst es fest einprägen. Denn die an Gott gläubig geworden sind, sollen auch darauf bedacht sein, sich guter Werke zu befleißigen. Das ist heilsam und bringen den Menschen Segen.',
        9: 'Dagegen den törichten Grübeleien über die Geschlechterreihen und den Zänkereien und Streitigkeiten über das Gesetz geh aus dem Weg! Denn das ist nutzlos und unfruchtbar.',
        10: 'Wer einer falschen Lehre folgt, den meide, wenn du ihn zweimal (vergeblich) zurechtgewiesen hast!',
        11: 'Du weißt ja: ein solcher Mensch ist aus der rechten Bahn geraten und zieht sich durch seine Sünde selbst das Urteil zu.',
        12: 'Sobald ich Artemas oder Tychikus zu dir sende, komme eiligst zu mir nach Nikopolis! Denn dort gedenke ich den Winter über zu bleiben.',
        13: 'Zenas, den Gesetzeslehrer, und Apollos rüste sorgfältig zur Weiterreise aus, damit es ihnen an nichts fehle!',
        14: 'Auch unsere Leute sollen lernen, da, wo es nottut, hilfreich einzutreten, damit sie Früchte (ihres Glaubens) aufzuweisen haben.',
        15: 'Alle, die bei mir sind, lassen dich grüßen. Grüße die Gläubigen, die uns liebhaben! Die Gnade sei mit euch allen!',
    },
}
